/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_args">_args</param>
public static void main(Args    _args)
{
    KCS_KBVBuildingProjectTable         buildingProjectTable;
    KCS_KBVRequestTable                 requestTable;
    KCS_KBVInquirerOfTheRequest         inquireRequest;
    ;

    void selectInquiries(KCS_KBVRequestId       _requestId, KCS_KBVBuildingProjectID        _buildingProjectId)
    {
        while  select inquireRequest
                where inquireRequest.KCS_KBVRequestID           == _requestId
                   && inquireRequest.KCS_KBVBuildingProjectID   == _buildingProjectId
        {
            KCS_KBVSearchTable::setFromCommonField(inquireRequest.KCS_KBVBuildingProjectID,inquireRequest,fieldNum(KCS_KBVInquirerOfTheRequest,DirPartyId));
            KCS_KBVSearchTable::setFromCommonField(inquireRequest.KCS_KBVBuildingProjectID,inquireRequest,fieldNum(KCS_KBVInquirerOfTheRequest,ContactPersonId));
        }
    }

    void selectRequestTable(KCS_KBVBuildingProjectID        _buildingProjectId)
    {
        while select requestTable
            where requestTable.KCS_KBVBuildingProjectID == _buildingProjectId
        {
            KCS_KBVSearchTable::setFromCommonField(requestTable.KCS_KBVBuildingProjectID,requestTable,fieldNum(KCS_KBVRequestTable,DirPartyId));
            KCS_KBVSearchTable::setFromCommonField(requestTable.KCS_KBVBuildingProjectID,requestTable,fieldNum(KCS_KBVRequestTable,ContactPersonId));
            selectInquiries(requestTable.KCS_KBVRequestID,requestTable.KCS_KBVBuildingProjectID);

        }

    }

    while select buildingProjectTable
    {
        KCS_KBVSearchTable::setFromCommonField(buildingProjectTable.KCS_KBVBuildingProjectID,buildingProjectTable,fieldNum(KCS_KBVBuildingProjectTable,KCS_KBVSubject));
        changecompany('NDX')
        {
            selectRequestTable(buildingProjectTable.KCS_KBVBuildingProjectID);

        }
        changecompany('HKL')
        {
            selectRequestTable(buildingProjectTable.KCS_KBVBuildingProjectID);

        }
        changecompany('NDG')
        {
            selectRequestTable(buildingProjectTable.KCS_KBVBuildingProjectID);

        }

    }
}
